"""Two independent blinded human forms; no labels are filled by automation."""
from common_adjusted import *
import random,html

def main():
 d=O/'P4';d.mkdir(exist_ok=False);pub=read(O/'data/PUBLIC_OUTPUTS.json');oldsrc={x['id']:x for x in read(BASE/'materials02/T4.json')};pool={}
 for method,rr in pub.items():
  for r in rr:pool.setdefault('T4|'+r['source_id'],dict(source_id=r['source_id'],dataset='T4',original=oldsrc[r['source_id']]['text'],versions={}))['versions'][method]=Path(r['text_path']).read_text(encoding='utf8')
 excluded=[]
 for r in read(O/'T5_insertion/INSERT_T5_all_RESULT.json')['rows']:
  if r['status']!='PREDICTED_TARGET_REACHED':continue
  verified=read(O/'T5_evaluation/records'/(r['id']+'.json'))
  if not all(verified.get(k) is True for k in ['certificate','anchor_invariant','selection_invariant']):
   excluded.append(dict(id=r['id'],reason='EMBEDDING_INVARIANT_NOT_VERIFIED',checks={k:verified.get(k) for k in ['certificate','anchor_invariant','selection_invariant']}));continue
  sid=r['source_id'];pool.setdefault('T5|'+sid,dict(source_id=sid,dataset='T5',original=(O/'P3/outputs'/('T5__'+sid+'.txt')).read_text(encoding='utf8'),versions={}))['versions'][r['method']]=(O/'T5_insertion/outputs'/(r['id']+'.txt')).read_text(encoding='utf8')
 chosen=sorted([v for v in pool.values() if set(v['versions'])=={'CertInsert','RC'}],key=lambda x:rank('blind_source',x['dataset']+'|'+x['source_id']))[:50];items=[];mapping=[]
 for i,x in enumerate(chosen):
  for method,text in [('Original',x['original']),*x['versions'].items()]:
   ident='H'+rank('blind_id',x['dataset']+'|'+x['source_id']+'|'+method)[:12];items.append(dict(id=ident,text=text,source_reference=x["original"]));mapping.append(dict(id=ident,source_id=x['source_id'],dataset=x['dataset'],method=method,text_sha256=hashlib.sha256(text.encode()).hexdigest()))
 private=O/'private_review_mapping';private.mkdir(exist_ok=True);put(private/'P4_METHOD_MAPPING.json',mapping)
 for reviewer in ['A','B']:
  aa=sorted(items,key=lambda x:rank('review_order_'+reviewer,x['id']));data=json.dumps(aa,ensure_ascii=False).replace('</','<\\/');template='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>独立文本审核</title><style>body{max-width:960px;margin:30px auto;font:17px/1.7 sans-serif}pre{white-space:pre-wrap;background:#f7f7f7;padding:22px}textarea{width:95%;height:70px}select,button{font-size:17px;margin:8px}</style><h1>独立文本审核 · REVIEWER</h1><p>请独立评判，不与另一位审核者商议。方法与插入位置均已隐藏。每项附相同原始材料供核对新增关系；原文对照可能因字面相同被识别，因此不是完全身份盲化。每完成20项请导出备份；当前无默认标签。</p><button onclick="exportJSON()">导出JSON</button><div id="root"></div><script>const data=DATA, reviewer='REVIEWER', key='HSW-E3-P4-'+reviewer;let answers=JSON.parse(localStorage.getItem(key)||'{}');function save(){localStorage.setItem(key,JSON.stringify(answers))}function field(id,k,v){(answers[id]??={})[k]=v;save()}for(const [i,x] of data.entries()){let sec=document.createElement('section');let h=document.createElement('h2');h.textContent=(i+1)+' / '+data.length+' · '+x.id;sec.appendChild(h);let reference=document.createElement('details');let label=document.createElement('summary');label.textContent='查看原始材料（用于核对知识与新增关系）';reference.appendChild(label);let reftext=document.createElement('pre');reftext.textContent=x.source_reference;reference.appendChild(reftext);sec.appendChild(reference);let pre=document.createElement('pre');pre.textContent=x.text;sec.appendChild(pre);for(const [k,label,opts] of [['naturalness','自然度（1最低，5最高）',['1','2','3','4','5']],['added_relation','是否新增时间先后、因果、强调或对比关系',['是','否']],['knowledge_error','是否存在知识错误',['是','否']]]){let l=document.createElement('label');l.textContent=label;let s=document.createElement('select');for(let v of ['',...opts]){let o=document.createElement('option');o.value=v;o.textContent=v||'请选择';s.appendChild(o)}s.value=answers[x.id]?.[k]||'';s.onchange=()=>field(x.id,k,s.value);l.appendChild(s);sec.appendChild(l);sec.appendChild(document.createElement('br'))}let t=document.createElement('textarea');t.placeholder='新增关系标为是时，请引用具体句子；知识错误请说明依据。';t.value=answers[x.id]?.evidence||'';t.oninput=()=>field(x.id,'evidence',t.value);sec.appendChild(t);document.getElementById('root').appendChild(sec)}function exportJSON(){let v={reviewer,exported:new Date().toISOString(),items:data.map(x=>({id:x.id,...answers[x.id]}))};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'}));a.download='independent_review_'+reviewer+'.json';a.click();URL.revokeObjectURL(a.href)}</script></html>''';(d/('REVIEW_'+reviewer+'.html')).write_text(template.replace('DATA',data).replace('REVIEWER',reviewer),encoding='utf8')
 put(d/'STATUS.json',dict(source_count=len(chosen),versions=len(items),reviewers=2,status='WAITING_TWO_INDEPENDENT_HUMANS',naturalness_mean=None,added_relation=None,knowledge_error=None,kappa=None,mapping_included_in_review_package=False,source_reference_provided=True,blinding='Method labels and insertion marks hidden; exact original-control matching remains possible',eligibility='Both methods predicted target reached and byte/anchor/selection invariants verified; no semantic quality or detection-score filtering',T5_invariant_exclusions=excluded));print('P4',len(chosen),'sources',len(items),'versions')
if __name__=='__main__':main()
